import {types,escape as e,visibleQuestions,cleanAnswers,questionHTML,readAnswer,validateAnswer} from './form-engine.js';
import {downloadWord} from './word-export.js';
const $=(s,r=document)=>r.querySelector(s),app=$('#app'),dlg=$('#dialog');
const S={boot:null,nav:'surveys',version:null,owner:null,history:[],section:0,dirty:false,preview:false,search:'',filter:'all',sort:'recent',page:0,client:null,clientTab:'assignments',results:null,offset:0,resultVersion:'',includeExcluded:false,collect:null,answerIndex:0,answers:{},queue:[],offline:false};
const messages={unauthorized:'Your session has expired. Sign in again to continue.',forbidden:'Your account does not have access to this action.',password_change_required:'Change your initial password before continuing.',conflict:'This item changed in another window. Reopen it to load the latest version.',service_unavailable:'The service is unavailable. Please try again.',not_published:'Only published surveys can be assigned.',review_note_required:'Add a review note before continuing.'};
async function request(path,body){const r=await fetch('/fieldwork-api/'+path,{method:body===undefined?'GET':'POST',credentials:'same-origin',headers:body===undefined?{}:{'content-type':'application/json'},body:body===undefined?undefined:JSON.stringify(body),cache:'no-store'});let d;try{d=await r.json()}catch{throw new Error('The service is unavailable. Please try again.')}if(!r.ok||d.error){if(d.error==='unauthorized'&&S.boot)S.needsSignIn=true;const error=new Error(d.message||messages[d.error]||'The request could not be completed.');error.code=d.error;error.questionId=d.questionId;throw error;}return d;}
const api=(op,p={})=>request('studio',{op,...p});
function toast(s){const el=$('#toast');el.textContent=s;el.style.display='block';clearTimeout(toast.t);toast.t=setTimeout(()=>el.style.display='none',5000);}
function date(s){return s?new Date(s).toLocaleDateString(undefined,{day:'numeric',month:'short',year:'numeric'}):'—';}
const pill=s=>`<span class="pill ${e(s)}">${e(s.replaceAll('_',' '))}</span>`;
const btn=(text,action,cls='',attrs='')=>`<button class="${cls}" data-action="${action}" ${attrs}>${text}</button>`;
const empty=(title,text)=>`<div class="empty"><h3>${e(title)}</h3><p>${e(text)}</p></div>`;
function dialog(title,body){dlg.innerHTML=btn('✕','close','quiet close','aria-label="Close dialog"')+`<h2>${e(title)}</h2>`+body;dlg.showModal();}
function closeDialog(){dlg.close();dlg.innerHTML='';}
function confirmLeave(){return !S.dirty||confirm('You have unsaved changes. Leave without saving them?');}
function markDirty(){S.dirty=true;const n=$('#save-state');if(n)n.textContent='Unsaved changes';}
function initials(name){return name.split(' ').map(x=>x[0]).slice(0,2).join('');}
function shell(html,crumb='Survey library'){
 const b=S.boot,p=b.permissions,nav=[['surveys','▤','Survey library'],['collection','▧','Assigned surveys'],...((b.clients.some(c=>c.canViewResults)||p.admin)?[['clients','◫','Clients & distribution']]:[]),...(p.admin?[['roles','♙','Access & roles']]:[])];
 app.innerHTML=`<div class="shell"><button class="menu-backdrop" aria-label="Close navigation" data-action="menu"></button><aside class="side"><div class="logo-plate"><img src="/fieldwork/agrighar-logo.jpeg" alt="Agrighar"></div><div class="eyebrow">Administration workspace</div><div class="studio-name">Survey Studio</div><nav>${nav.map(([id,icon,title])=>btn(`<span class="ico" aria-hidden="true">${icon}</span>${title}`,'nav','nav-item '+(S.nav===id?'active':''),`data-nav="${id}"`)).join('')}</nav><div class="side-foot">Create. Review. Publish.<br>Private results for each client.<br><br><a href="/fieldwork/index.html">← Fieldwork application</a><br><br>Service provider for the<br>State of Jigawa</div></aside><div class="workspace"><header class="topbar">${btn('☰','menu','hamburger','aria-label="Open navigation"')}<img class="mobile-logo" src="/fieldwork/agrighar-logo.jpeg" alt="Agrighar"><span class="crumb">Workspace <span aria-hidden="true"> / </span> <b>${e(crumb)}</b></span><div class="account"><span class="online ${S.offline||!navigator.onLine?'offline':''}">${S.offline||!navigator.onLine?'Offline':'Connected'}</span><span class="avatar">${e(initials(b.account.name))}</span><span class="account-name">${e(b.account.name)}</span>${S.needsSignIn||S.offline?btn('Sign in again','reauth','small'):''}${btn('Sign out','logout','quiet small')}</div></header><main id="main" class="content">${html}</main></div></div>`;
}
function login(error='',passwordChange=false){app.innerHTML=`<main class="login"><img src="/fieldwork/agrighar-logo.jpeg" alt="Agrighar"><div class="eyebrow">Agrighar administration</div><h1>${passwordChange?'Set your password':'Welcome to Survey Studio'}</h1><p class="muted">${passwordChange?'Choose a private password to secure your account.':'Design better questions. Deliver trusted field insights.'}</p>${error?`<p class="notice error" role="alert">${e(error)}</p>`:''}<form id="${passwordChange?'password-form':'login-form'}">${passwordChange?'':`<label>Phone number / user ID<input name="userId" inputmode="numeric" autocomplete="username" maxlength="18" required></label>`}<label>${passwordChange?'New password':'Password'}<input name="password" type="password" autocomplete="${passwordChange?'new-password':'current-password'}" minlength="${passwordChange?12:1}" maxlength="72" required></label>${passwordChange?'<small>At least 12 characters, with uppercase, lowercase, a number and a symbol.</small>':''}<button class="primary" type="submit">${passwordChange?'Save password':'Sign in'} →</button></form><small>Use your existing Agrighar fieldwork account.<br>Results are available only to the assigned client’s admin and leadership team.</small><p><a href="/fieldwork/index.html">Return to Fieldwork</a></p></main>`;}
async function boot(){try{S.boot=await api('bootstrap');S.offline=false;S.needsSignIn=false;await cacheSet('identity',{account:S.boot.account,until:Date.now()+7*86400000});await syncQueue();if(new URLSearchParams(location.search).get('campaign')){S.nav='collection';await openCampaign(new URLSearchParams(location.search).get('campaign'));}else library();}catch(err){if(!navigator.onLine){let saved=await cacheGet('identity');if(saved&&saved.until>Date.now()){S.boot={account:saved.account,permissions:{},clients:[],versions:[]};S.offline=true;S.nav='collection';await collection();return;}}login(err.code==='unauthorized'?'':err.message,err.code==='password_change_required');}}
function library(){S.nav='surveys';const versions=S.boot.versions;const state=['draft','in_review','approved','published'];let rows=versions.filter(v=>(S.filter==='all'||v.state===S.filter)&&(v.title+' '+v.ownerName).toLowerCase().includes(S.search.toLowerCase()));rows.sort(S.sort==='title'?(a,b)=>(a.title||'').localeCompare(b.title||''):(a,b)=>new Date(b.updatedAt)-new Date(a.updatedAt));S.page=Math.min(S.page,Math.max(0,Math.ceil(rows.length/12)-1));shell(`<div class="page-head"><div><div class="eyebrow">Your research, thoughtfully designed</div><h1>Survey library</h1><p>Build a questionnaire, have it reviewed, and publish a version clients can use.</p></div><div class="actions">${S.boot.permissions.create?btn('＋ Create survey','create','primary'):''}</div></div><div class="stats">${state.map(s=>`<div class="stat"><small>${e({draft:'Drafts',in_review:'Awaiting review',approved:'Ready to publish',published:'Published versions'}[s])}</small><b>${versions.filter(v=>v.state===s).length}</b></div>`).join('')}</div><div class="row between"><h2>All surveys <small>(${versions.length})</small></h2><span class="desktop-note">Published versions are fixed and reusable</span></div><div class="filters"><input id="library-search" aria-label="Search surveys" placeholder="Search surveys or creators…" value="${e(S.search)}"><select id="library-filter" aria-label="Survey status"><option value="all">All statuses</option>${state.map(s=>`<option value="${s}" ${S.filter===s?'selected':''}>${e(s.replaceAll('_',' '))}</option>`).join('')}</select><select id="library-sort" aria-label="Sort surveys"><option value="recent">Recently updated</option><option value="title" ${S.sort==='title'?'selected':''}>Title A–Z</option></select></div><div class="grid">${rows.slice(S.page*12,S.page*12+12).map(v=>`<article class="card survey-card"><div class="row between">${pill(v.state)}<small>Version ${v.version}</small></div><h3>${e(v.title||'Untitled survey')}</h3><p>${e(v.description||'No description yet.')}</p><div class="row muted"><small>${e(v.ownerName)} · ${date(v.updatedAt)}</small></div><div class="foot"><small>${v.ownerId===S.boot.account.id?'Created by you':v.state==='published'?'Reusable questionnaire':'Review workspace'}</small>${btn(v.state==='draft'&&v.ownerId===S.boot.account.id?'Edit survey →':'Open survey →','open-version','small quiet',`data-id="${v.id}"`)}</div></article>`).join('')}</div>${!rows.length?empty('Start with a good question',S.boot.permissions.create?'Create your first survey or adjust your filters.':'Assigned published surveys and questionnaires you can review will appear here.'):''}<div class="pagination">${btn('← Previous','library-prev','small',S.page===0?'disabled':'')}<span>Page ${S.page+1} of ${Math.max(1,Math.ceil(rows.length/12))}</span>${btn('Next →','library-next','small',(S.page+1)*12>=rows.length?'disabled':'')}</div>`);}
async function refresh(){S.boot=await api('bootstrap');}
function newDefinition(){return {title:'Untitled survey',description:'',sections:[{id:'s'+crypto.randomUUID().replaceAll('-',''),title:'Section 1',description:'',questions:[]}]};}
async function openVersion(id){const r=await api('version',{versionId:id});S.version=r.version;S.owner=r.ownerId;S.history=r.history||[];S.section=0;S.dirty=false;S.preview=false;editor();}
function canEdit(){return Boolean(S.boot&&S.version&&S.owner===S.boot.account.id&&S.version.state==='draft'&&S.boot.permissions.create);}
const input=(label,field,value,extra='')=>`<label>${label}<input data-field="${field}" value="${e(value??'')}" ${extra}></label>`;
function editor(){S.nav='surveys';const v=S.version,d=v.definition,s=d.sections[S.section],editable=canEdit(),isOwner=S.owner===S.boot.account.id,p=S.boot.permissions;const controls=`${btn('Download Word','word','small')}${btn(S.preview?'Builder':'Preview','toggle-preview','small')}${editable?btn('Save draft','save','primary small'):''}`;let actions='';if(editable)actions=btn('Request review →','request-review','primary');if(isOwner&&v.state==='in_review')actions=btn('Return to editing','cancel-review');if(v.state==='in_review'&&p.review&&!isOwner)actions=btn('Return with feedback','review-return')+btn('Approve survey','review-approve','primary');if(v.state==='approved'&&p.publish)actions=btn('Publish survey →','publish','primary');if(!editable&&p.create)actions+=btn(isOwner?'Create next version':'Copy to new draft','fork');
 shell(`<div class="page-head"><div><div class="row">${btn('← Library','library','quiet small')}${pill(v.state)}<small>Version ${v.version}</small></div><h1>${e(d.title||'Untitled survey')}</h1><p><span id="save-state">${S.dirty?'Unsaved changes':'All changes saved'}</span> · ${d.sections.reduce((n,s)=>n+s.questions.length,0)} questions</p></div><div class="actions">${controls}</div></div><div class="step-track">${['draft','in_review','approved','published'].map((st,i)=>`<span class="${v.state===st?'current':''}">${i+1}. ${['Create','Review','Approve','Publish'][i]}</span>`).join('')}</div>${v.review_note?`<div class="notice"><b>Review feedback</b><br>${e(v.review_note)}</div>`:''}${v.state==='published'?'<div class="notice">This published version is fixed. Assign it to a client from Clients & distribution, or copy it to make changes.</div>':''}${S.preview?previewAll(d):`<div class="builder"><aside class="outline card"><div class="eyebrow">Survey sections</div><div class="section-list">${d.sections.map((sec,i)=>btn(`${i+1}. ${e(sec.title||'Untitled section')}`,'section',i===S.section?'selected':'',`data-index="${i}"`)).join('')}</div>${editable?btn('＋ Add section','add-section','quiet small'):''}<div class="space"></div><small>${editable?'Select a section to edit its questions.':'Read-only questionnaire'}</small></aside><div class="editor">${S.section===0?`<section class="card"><h2>Survey details</h2>${editable?`<input class="survey-title" data-field="title" aria-label="Survey title" maxlength="200" value="${e(d.title)}"><label>Introduction<textarea data-field="description" maxlength="10000" placeholder="Explain the purpose of this survey…">${e(d.description)}</textarea></label>`:`<h3>${e(d.title)}</h3><p>${e(d.description)}</p>`}</section>`:''}<section class="card">${editable?`${input('Section title','section-title',s.title,'maxlength="200"')}<label>Section description<textarea data-field="section-description" maxlength="10000">${e(s.description)}</textarea></label><div class="section-actions">${btn('↑ Move','section-up','small',S.section===0?'disabled':'')}${btn('↓ Move','section-down','small',S.section===d.sections.length-1?'disabled':'')}${btn('Remove section','remove-section','small danger',d.sections.length===1?'disabled':'')}</div>`:`<h2>${e(s.title)}</h2><p>${e(s.description||'')}</p>`}</section>${s.questions.map((q,i)=>editable?questionEditor(q,i):`<section class="card question">${questionHTML(q)}</section>`).join('')}${editable?btn('＋ Add question','add-question','full'):''}${!s.questions.length?empty('A fresh section','Add a question to begin.'):''}</div></div>`}<div class="card row between" style="margin-top:24px"><small>${v.state==='draft'?'Save your changes before sending for an independent review.':v.state==='in_review'?'A reviewer other than the creator must approve this survey.':v.state==='approved'?'Approved and ready for a publisher to release.':'Ready for client assignment and distribution.'}</small><div class="actions review-actions">${actions}</div></div><details><summary>Version history</summary><div class="history">${S.history.map(h=>`<p><b>${e(h.action.replaceAll('_',' '))}</b>${e(h.actor)} · ${date(h.at)}${h.note?'<br>'+e(h.note):''}</p>`).join('')||'<p>No history yet.</p>'}</div></details>`,'Survey builder');
 if(!editable&&!S.preview)$('#main').querySelectorAll('[data-answer]').forEach(el=>el.disabled=true);
}
function questionEditor(q,i){const opts=['single_choice','multiple_choice','dropdown','single_choice_grid','multiple_choice_grid'].includes(q.type),prior=S.version.definition.sections.flatMap(s=>s.questions).slice(0,S.version.definition.sections.flatMap(s=>s.questions).findIndex(x=>x.id===q.id)).filter(x=>['single_choice','multiple_choice','dropdown','yes_no'].includes(x.type));return `<section class="card question" data-qindex="${i}" id="question-${e(q.id)}"><div class="q-top"><span class="eyebrow">Question ${i+1}</span><select aria-label="Question ${i+1} type" data-qfield="type">${Object.entries(types).map(([k,v])=>`<option value="${k}" ${q.type===k?'selected':''}>${v}</option>`).join('')}</select><div class="tools">${btn('↑','q-up','small quiet',`data-index="${i}" aria-label="Move question up" ${i===0?'disabled':''}`)}${btn('↓','q-down','small quiet',`data-index="${i}" aria-label="Move question down" ${i===S.version.definition.sections[S.section].questions.length-1?'disabled':''}`)}</div></div><label>Question<input class="label" data-qfield="label" maxlength="1000" value="${e(q.label)}" placeholder="What would you like to ask?"></label><label>Help text <small>(optional)</small><input data-qfield="help" maxlength="5000" value="${e(q.help||'')}" placeholder="Add a hint or instruction"></label>${opts?`<label>Answer options <small>(one per line; 2–80 options)</small><textarea data-qfield="options">${e((q.options||[]).join('\n'))}</textarea></label>`:''}${q.type.includes('grid')?`<label>Grid rows <small>(one per line)</small><textarea data-qfield="rows">${e((q.rows||[]).join('\n'))}</textarea></label>`:''}${q.type==='number'?`<div class="two">${input('Minimum','q-min',q.min,'type="number" data-qfield="min"')}${input('Maximum','q-max',q.max,'type="number" data-qfield="max"')}</div><label class="row"><input type="checkbox" data-qfield="integer" ${q.integer?'checked':''}> Whole numbers only</label>`:''}${q.type==='rating'?`<label>Rating scale<select data-qfield="max">${[3,4,5,7,10].map(n=>`<option value="${n}" ${(q.max||5)===n?'selected':''}>1 to ${n}</option>`).join('')}</select></label>`:''}<div class="row between"><label class="row"><input type="checkbox" data-qfield="required" ${q.required?'checked':''} ${q.type==='statement'?'disabled':''}> Required</label><div class="row">${btn('Duplicate','q-copy','small quiet',`data-index="${i}"`)}${btn('Remove','q-remove','small quiet danger',`data-index="${i}"`)}</div></div><details ${q.conditions?.length?'open':''}><summary>${q.conditions?.length?'Conditional display enabled':'Show this question conditionally'}</summary><p class="desktop-note">All conditions must match. Each condition can accept multiple answers.</p>${(q.conditions||[]).map((c,ci)=>`<div class="notice"><label>Earlier question<select data-condition="${ci}" data-condition-field="questionId"><option value="">Select a question</option>${prior.map(p=>`<option value="${e(p.id)}" ${p.id===c.questionId?'selected':''}>${e(p.label||'Untitled question')}</option>`).join('')}</select></label>${conditionChoices(c,prior,ci)}${btn('Remove condition','condition-remove','small quiet',`data-index="${i}" data-condition-index="${ci}"`)}</div>`).join('')}${prior.length?btn('＋ Add condition','condition-add','small',`data-index="${i}"`):'<small>Add a choice question earlier in the survey first.</small>'}</details><small class="tag-id">${e(q.id)}</small></section>`;}
function conditionChoices(c,prior,ci){const ref=prior.find(p=>p.id===c.questionId),options=ref?.type==='yes_no'?['Yes','No']:ref?.options||[];return '<label>Show for any of these answers</label>'+options.map(o=>`<label class="row"><input type="checkbox" data-condition="${ci}" data-condition-option="${e(o)}" ${c.values.includes(o)?'checked':''}>${e(o)}</label>`).join('');}
function previewAll(d){return `<div class="collector"><div class="notice">Questionnaire preview · No responses are saved. All questions and display rules are shown for review.</div>${d.sections.map(s=>`<section class="card" style="margin-bottom:18px"><h2>${e(s.title)}</h2><p>${e(s.description||'')}</p>${s.questions.map(q=>questionHTML(q)+(q.conditions?.length?`<p class="notice warning">Shown when ${e(q.conditions.map(c=>c.questionId+' = '+c.values.join(' or ')).join(' AND '))}</p>`:'')).join('')}</section>`).join('')}</div>`;}
function mutateStructure(fn){if(!canEdit())return;fn();markDirty();editor();}
async function save(){if(!canEdit())return;const r=await api('save',{versionId:S.version.id,revision:S.version.revision,definition:S.version.definition});S.version=r.version;S.dirty=false;editor();toast('Draft saved');}
async function transition(op,extra={}){if(S.dirty)await save();const r=await api(op,{versionId:S.version.id,revision:S.version.revision,...extra});S.version=r.version;S.dirty=false;await refresh();await openVersion(r.version.id);toast(op==='publish'?'Survey published':op==='request_review'?'Sent for independent review':'Workflow updated');}
function clients(){S.nav='clients';S.client=null;shell(`<div class="page-head"><div><div class="eyebrow">Client workspaces</div><h1>Clients & distribution</h1><p>Assign published surveys, organise collection campaigns, and manage each client’s team.</p></div>${S.boot.permissions.admin?btn('＋ Add client','create-client','primary'):''}</div><div class="notice">Results are private to each client’s admin and leadership team. Creating or publishing a survey does not grant access to its responses.</div><div class="grid">${S.boot.clients.filter(c=>c.canViewResults||S.boot.permissions.admin).map(c=>`<article class="card survey-card"><div class="row between"><span class="pill">${e(c.role||'Platform admin')}</span><span aria-hidden="true">◫</span></div><h3>${e(c.name)}</h3><p>${c.canViewResults?'Manage distributions and view this client’s results.':'Manage assignments and team access. Result access is restricted.'}</p><div class="foot"><small>${c.canViewResults?'Results access enabled':'Assignment access only'}</small>${btn('Open client →','open-client','small quiet',`data-id="${c.id}"`)}</div></article>`).join('')}</div>${!S.boot.clients.length?empty('No client workspaces yet','A Studio administrator can create a client and appoint its first admin.'):''}`,'Clients & distribution');}
async function openClient(id){S.client=await api('client',{clientId:id});S.clientTab='assignments';S.resultVersion='';S.includeExcluded=false;S.offset=0;clientView();}
function clientView(){const c=S.client,p=S.boot.permissions,manager=c.canViewResults,memberRole=S.boot.clients.find(x=>x.id===c.client.id)?.role,canMembers=p.admin||memberRole==='admin';const tabs=[['assignments','Assigned surveys'],['campaigns','Distribution'],['members','Client team'],...(manager?[['results','Results'],['audit','Activity']]:[])];let body='';if(S.clientTab==='assignments'){body=`<div class="row between"><h2>Published & assigned</h2>${p.publish?btn('＋ Assign published survey','assign-dialog','primary small'):''}</div><p class="muted">Only a published version can be assigned. Changes require a new draft, review and publication.</p><div class="grid">${c.assignments.map(a=>`<article class="card"><div class="row between">${pill(a.active?'published':'paused')}<small>Version ${a.version}</small></div><h3 style="margin-top:20px">${e(a.title)}</h3><div class="actions">${btn('Open','open-version','small',`data-id="${a.versionId}"`)}${manager&&a.active?btn('Distribute','campaign-dialog','primary small',`data-id="${a.id}"`):''}${S.boot.permissions.create&&a.active?btn('Copy to draft','copy-assigned','small',`data-id="${a.versionId}"`):''}${p.publish?btn(a.active?'Pause assignment':'Resume assignment','assignment-status','quiet small',`data-id="${a.id}" data-active="${!a.active}"`):''}</div></article>`).join('')}</div>${!c.assignments.length?empty('No surveys assigned','Publish a questionnaire, then assign its published version to this client.'):''}`;}else if(S.clientTab==='campaigns'){body=`<h2>Collection campaigns</h2><p class="muted">Distribute an assigned survey to this client’s active team using a sign-in link. Create a new campaign to reuse the same questionnaire.</p><div class="table-wrap"><table><thead><tr><th>Campaign</th><th>Survey version</th><th>Status</th><th>Actions</th></tr></thead><tbody>${c.campaigns.map(x=>`<tr><td class="wrap">${e(x.name)}</td><td class="wrap">${e(x.title)} · v${x.version}</td><td>${pill(x.active?'active':'paused')}</td><td><div class="row">${manager?btn('Copy sign-in link','copy-link','small',`data-id="${x.id}"`)+btn(x.active?'Pause':'Resume','campaign-status','small quiet',`data-id="${x.id}" data-active="${!x.active}"`):''}</div></td></tr>`).join('')}</tbody></table></div>${!c.campaigns.length?empty('Ready to distribute?','Choose Distribute on an assigned survey to create a collection campaign.'):''}`;}else if(S.clientTab==='members'){body=`<div class="row between"><h2>Client team</h2>${canMembers?btn('＋ Add or update member','member-dialog','primary small'):''}</div><div class="notice">Admin and leadership can view results. Collectors can complete assigned surveys and receive submission receipts. A survey creator must be explicitly added here as admin or leadership to access results.</div><div class="table-wrap"><table><thead><tr><th>Name</th><th>Login ID</th><th>Client role</th><th>Status</th><th></th></tr></thead><tbody>${c.members.map(m=>`<tr><td>${e(m.name)}</td><td>${e(m.loginId)}</td><td>${e(m.role)}</td><td>${m.active?'Active':'Inactive'}</td><td>${canMembers?btn('Edit access','member-dialog','small quiet',`data-id="${m.accountId}"`):''}</td></tr>`).join('')}</tbody></table></div>`;}else if(S.clientTab==='results'){body=resultsHTML();}else if(S.clientTab==='audit'){body=`<h2>Client activity</h2><div class="history">${(S.audit||[]).map(a=>`<p><b>${e(a.action.replaceAll('_',' '))}</b>${e(a.actor)} · ${date(a.at)}${a.note?'<br>'+e(a.note):''}</p>`).join('')||'<p>No activity yet.</p>'}</div>`;}
 shell(`<div class="page-head"><div>${btn('← Clients','clients','quiet small')}<div class="eyebrow">Client workspace</div><h1>${e(c.client.name)}</h1><p>${manager?'Your client’s surveys, team and private results.':'Assignments and access management. You do not have client result access.'}</p></div></div><div class="tabs">${tabs.map(([id,t])=>btn(t,'client-tab',S.clientTab===id?'active':'',`data-tab="${id}"`)).join('')}</div>${body}`,'Client · '+c.client.name);}
async function reloadClient(){S.client=await api('client',{clientId:S.client.client.id});await refresh();clientView();}
async function loadResults(){S.results=await api('results',{clientId:S.client.client.id,offset:S.offset,versionId:S.resultVersion,includeExcluded:S.includeExcluded});S.clientTab='results';clientView();}
function resultsHTML(){const r=S.results||{responses:[],total:0};return `<div class="row between"><div><h2>Private client results</h2><small>${r.total} matching responses · 25 per page · newest first</small></div>${btn('Refresh','refresh-results','small')}</div><div class="filters"><select id="result-version" aria-label="Filter results by survey"><option value="">All assigned surveys</option>${S.client.assignments.map(a=>`<option value="${a.versionId}" ${S.resultVersion===a.versionId?'selected':''}>${e(a.title)} · v${a.version}</option>`).join('')}</select><label class="row"><input id="result-excluded" type="checkbox" ${S.includeExcluded?'checked':''}> Include excluded responses</label></div><div class="table-wrap"><table><thead><tr><th>Survey / campaign</th><th>Collector</th><th>Captured</th><th>Submitted</th><th>Status</th><th></th></tr></thead><tbody>${r.responses.map(x=>`<tr><td class="wrap"><b>${e(x.title)}</b> · v${x.version}<br><small>${e(x.campaign)}</small></td><td>${e(x.collector)}</td><td>${e(x.captureDate)}</td><td>${date(x.submittedAt)}</td><td>${pill(x.excluded?'excluded':'included')}</td><td>${btn('View response','response','small',`data-id="${x.id}"`)}</td></tr>`).join('')}</tbody></table></div>${!r.total?empty('No matching responses','Submitted responses will appear here. Collectors and survey authors without client leadership access cannot open this view.'):''}<div class="pagination">${btn('← Previous','results-prev','small',S.offset===0?'disabled':'')}<span>${r.total?S.offset+1:0}–${Math.min(S.offset+25,r.total)} of ${r.total}</span>${btn('Next →','results-next','small',S.offset+25>=r.total?'disabled':'')}</div>`;}
async function response(id){const r=await api('response',{clientId:S.client.client.id,responseId:id});S.response=r;dialog('Survey response',`<p class="muted">${e(r.definition.title)} · Captured ${e(r.response.capture_date)} · Submitted ${date(r.response.submitted_at)}</p>${r.definition.sections.map(s=>`<h3>${e(s.title)}</h3>${s.questions.filter(q=>q.type!=='statement'&&r.response.answers[q.id]!==undefined).map(q=>`<p><b>${e(q.label)}</b></p><div class="response-value">${formatAnswer(r.response.answers[q.id])}</div>`).join('')}`).join('')}<div class="notice ${r.excluded?'warning':''}">${r.excluded?'Excluded from result lists and summaries. The original response is retained.':'Included in client results.'}</div><form id="flag-form"><label>Reason for changing result inclusion<textarea name="note" required maxlength="5000"></textarea></label><button class="${r.excluded?'primary':'danger'}" type="submit">${r.excluded?'Restore to results':'Exclude from results'}</button></form>`);}
function formatAnswer(a){if(Array.isArray(a))return e(a.join(', '));if(a&&typeof a==='object')return Object.entries(a).map(([k,v])=>e(k)+': '+e(Array.isArray(v)?v.join(', '):v)).join('<br>');return e(a);}
function roles(){S.nav='roles';shell(`<div class="page-head"><div><div class="eyebrow">Platform permissions</div><h1>Access & roles</h1><p>Choose who can create, review, publish and administer Survey Studio.</p></div>${btn('Update access','role-dialog','primary')}</div><div class="notice">Studio permissions grant access to questionnaires and workflow only. Client result access is controlled separately in each client’s team.</div><div class="table-wrap"><table><thead><tr><th>Account</th><th>Create</th><th>Review</th><th>Publish</th><th>Studio admin</th><th></th></tr></thead><tbody>${S.boot.roles.map(r=>`<tr><td>${e(S.boot.people.find(p=>p.id===r.account_id)?.name||'Account')}</td>${['can_create','can_review','can_publish','is_admin'].map(k=>`<td>${r[k]?'✓':'—'}</td>`).join('')}<td>${btn('Edit','role-dialog','quiet small',`data-id="${r.account_id}"`)}</td></tr>`).join('')}</tbody></table></div><div class="notice warning">A creator cannot approve their own survey. Another authorised reviewer must complete the review before publication.</div>`,'Access & roles');}
function memberDialog(id){const m=S.client.members.find(x=>x.accountId===id);dialog(m?'Update client member':'Add client member',`<p class="muted">Choose an existing Agrighar account using its 10-digit phone login ID.</p><form id="member-form"><label>Phone login ID<input name="loginId" inputmode="numeric" pattern="[0-9]{10}" maxlength="10" value="${e(m?.loginId||'')}" required></label><label>Client role<select name="role">${['collector','leadership','admin'].map(r=>`<option ${m?.role===r?'selected':''}>${r}</option>`).join('')}</select></label><p class="desktop-note">Leadership and admin can view all results for this client. Only admin can change team membership.</p><label class="row"><input name="active" type="checkbox" ${!m||m.active?'checked':''}> Active membership</label><button type="submit" class="primary">Save client access</button></form>`);}
function roleDialog(id){const r=S.boot.roles.find(x=>x.account_id===id);dialog('Studio permissions',`<form id="role-form"><label>Existing account<select name="accountId" required>${S.boot.people.map(p=>`<option value="${p.id}" ${p.id===id?'selected':''}>${e(p.name)}</option>`).join('')}</select></label>${[['create','can_create','Create surveys'],['review','can_review','Review surveys'],['publish','can_publish','Publish & assign surveys'],['admin','is_admin','Administer Studio and client access']].map(([k,key,t])=>`<label class="row"><input type="checkbox" name="${k}" ${r?.[key]?'checked':''}> ${t}</label>`).join('')}<div class="notice">Client results are not included in these permissions.</div><button class="primary" type="submit">Save permissions</button></form>`);}
// Only collection drafts and published collection schemas are cached. Client results never enter storage.
let storage;
async function store(){if(storage)return storage;storage=await new Promise((resolve,reject)=>{const r=indexedDB.open('agrighar-survey-studio',1);r.onupgradeneeded=()=>r.result.createObjectStore('collection');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});return storage;}
async function cacheGet(key){try{const db=await store();return await new Promise((resolve,reject)=>{const r=db.transaction('collection').objectStore('collection').get(key);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}catch{return null;}}
async function cacheSet(key,value){const db=await store();await new Promise((resolve,reject)=>{const tx=db.transaction('collection','readwrite');value===undefined?tx.objectStore('collection').delete(key):tx.objectStore('collection').put(value,key);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});}
const userKey=k=>S.boot.account.id+':'+k;
async function clearStorage(){const db=await store();await new Promise((resolve,reject)=>{const tx=db.transaction('collection','readwrite');tx.objectStore('collection').clear();tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});}
async function collection(){S.nav='collection';S.collect=null;let campaigns=[];if(!S.offline&&navigator.onLine){try{campaigns=(await api('collection_list')).campaigns;await cacheSet(userKey('campaigns'),campaigns);}catch(err){if(navigator.onLine)throw err;}}else campaigns=await cacheGet(userKey('campaigns'))||[];const queue=await cacheGet(userKey('queue'))||[];S.queue=queue;shell(`<div class="page-head"><div><div class="eyebrow">Field collection</div><h1>Assigned surveys</h1><p>Complete active surveys assigned to your client team. Downloaded questionnaires and drafts are available offline on this device.</p></div>${btn('Sync now','sync','primary')}</div>${queue.length?`<div class="notice warning"><b>${queue.length} ${queue.length===1?'response':'responses'} waiting to sync</b><p>Keep this device until a submission receipt confirms the upload. Reconnect and sign in if your session has expired. Paused campaigns or revoked access require your client admin’s help.</p>${queue.map(x=>`<p><small>${e(x.title)} · Captured ${date(x.capturedAt)}${x.syncError?'<br>'+e(x.syncError):''}</small>${x.syncCode==='invalid_answers'?btn('Correct response','fix-queued','small',`data-id="${x.responseId}"`):''}</p>`).join('')}</div>`:''}<div class="grid">${campaigns.map(c=>`<article class="card survey-card"><div class="row between"><span class="pill">${e(c.clientName)}</span><small>v${c.version}</small></div><h3>${e(c.title)}</h3><p>${e(c.name)}</p><div class="foot"><small>Signed-in team access</small>${btn('Open survey →','open-campaign','primary small',`data-id="${c.id}"`)}</div></article>`).join('')}</div>${!campaigns.length?empty('No active collection campaigns','Your client admin can create a campaign from an assigned published survey and add you to the client team.'):''}<div class="notice">Collectors receive submission receipts. Only client admin and leadership can view the collected results.</div>`,'Assigned surveys');}
async function openCampaign(id){let form;if(!S.offline&&navigator.onLine){form=await api('campaign_form',{campaignId:id});await cacheSet(userKey('form:'+id),form);}else{form=await cacheGet(userKey('form:'+id));if(!form||new Date(form.offlineUntil)<=new Date())throw new Error('Connect to the internet and open this survey once before collecting offline. Cached collection access lasts seven days.');}let draft=await cacheGet(userKey('draft:'+id));S.collect={...form,responseId:draft?.versionId===form.version.id?draft.responseId:crypto.randomUUID(),capturedAt:draft?.versionId===form.version.id?draft.capturedAt:new Date().toISOString()};S.answers=draft?.versionId===form.version.id?draft.answers:{};S.answerIndex=draft?.versionId===form.version.id?draft.index||0:0;S.collectReview=false;S.nav='collection';collector();await persistDraft();}
async function persistDraft(){if(!S.collect)return;await cacheSet(userKey('draft:'+S.collect.campaign.id),{versionId:S.collect.version.id,responseId:S.collect.responseId,capturedAt:S.collect.capturedAt,answers:S.answers,index:S.answerIndex});}
function collector(){const f=S.collect,d=f.version.definition,questions=visibleQuestions(d,S.answers),n=Math.min(S.answerIndex,Math.max(0,questions.length-1));S.answerIndex=n;const q=questions[n];let body;if(S.collectReview){body=`<h2>Review your answers</h2>${questions.filter(q=>q.type!=='statement').map(q=>`<div class="card" style="margin:12px 0"><div class="row between"><b>${e(q.label)}</b>${btn('Edit','edit-answer','quiet small',`data-id="${q.id}"`)}</div><div class="response-value">${formatAnswer(S.answers[q.id])||'<span class="muted">Not answered</span>'}</div></div>`).join('')}<div class="row between">${btn('← Back to questions','back-questions')}${btn(navigator.onLine&&!S.offline?'Submit survey':'Save for sync','submit-response','primary')}</div>`;}else body=`<div class="row between"><span class="eyebrow">${e(q?.sectionTitle||'Survey')}</span><small>Question ${n+1} / ${questions.length}</small></div><div class="progress"><i style="width:${Math.round((n+1)/Math.max(1,questions.length)*100)}%"></i></div><section class="card" id="active-question"><small>${e(q?.sectionDescription||'')}</small>${q?questionHTML(q,S.answers[q.id]):'<p>No questions.</p>'}<div id="answer-error" class="notice error" role="alert" hidden></div><div class="row between">${btn('← Back','answer-prev','',n===0?'disabled':'')}${btn(n===questions.length-1?'Review answers →':'Continue →','answer-next','primary')}</div></section>`;shell(`<div class="collector"><div class="page-head"><div><div class="eyebrow">${e(f.campaign.clientName)} · ${e(f.campaign.name)}</div><h1>${e(d.title)}</h1><p>${e(d.description||'')}</p></div>${btn('Save & close','close-collection','small')}</div><p class="desktop-note">Captured ${date(f.capturedAt)} · Questionnaire v${f.version.version} · Draft saved on this device</p>${body}</div>`,'Survey collection');if(!S.collectReview)requestAnimationFrame(()=>{$('#active-question')?.scrollIntoView({block:'nearest',behavior:'smooth'});});}
function captureActive(){if(!S.collect||S.collectReview)return;const q=visibleQuestions(S.collect.version.definition,S.answers)[S.answerIndex];if(q){const value=readAnswer($('#active-question'),q,S.answers[q.id]);if(value!==undefined)S.answers[q.id]=value;}return q;}
async function nextAnswer(delta){const q=captureActive();if(delta>0&&q){const problem=validateAnswer(q,S.answers[q.id]);if(problem){$('#answer-error').textContent=problem;$('#answer-error').hidden=false;$('#active-question [data-answer]')?.focus();return;}}await persistDraft();const qs=visibleQuestions(S.collect.version.definition,S.answers);if(delta>0&&S.answerIndex>=qs.length-1)S.collectReview=true;else S.answerIndex=Math.max(0,S.answerIndex+delta);collector();await persistDraft();}
async function submitResponse(){const f=S.collect,qs=visibleQuestions(f.version.definition,S.answers);for(let i=0;i<qs.length;i++){let problem=validateAnswer(qs[i],S.answers[qs[i].id]);if(problem){S.collectReview=false;S.answerIndex=i;collector();toast(problem);return;}}const entry={campaignId:f.campaign.id,responseId:f.responseId,versionId:f.version.id,title:f.version.definition.title,answers:cleanAnswers(f.version.definition,S.answers),capturedAt:f.capturedAt};const queue=await cacheGet(userKey('queue'))||[];if(!queue.some(x=>x.responseId===entry.responseId))queue.push(entry);await cacheSet(userKey('queue'),queue);await cacheSet(userKey('draft:'+f.campaign.id),undefined);S.collect=null;S.answers={};if(navigator.onLine&&!S.offline)await syncQueue();await collection();toast((await cacheGet(userKey('queue'))||[]).some(x=>x.responseId===entry.responseId)?'Response saved on this device. Waiting to sync.':'Survey submitted. Receipt confirmed.');}
let syncing=false;
async function syncQueue(){if(syncing||!S.boot||S.offline||!navigator.onLine)return;syncing=true;try{let queue=await cacheGet(userKey('queue'))||[];for(const entry of [...queue]){try{const r=await api('submit',{campaignId:entry.campaignId,responseId:entry.responseId,answers:entry.answers,capturedAt:entry.capturedAt});if(r.receipt){queue=(await cacheGet(userKey('queue'))||[]).filter(x=>x.responseId!==entry.responseId);await cacheSet(userKey('queue'),queue);}}catch(err){queue=await cacheGet(userKey('queue'))||[];const pending=queue.find(x=>x.responseId===entry.responseId);if(pending){pending.syncError=err.message;pending.syncCode=err.code;pending.questionId=err.questionId;}await cacheSet(userKey('queue'),queue);if(err.code==='unauthorized')break;}}}finally{syncing=false;}}
async function action(el){const a=el.dataset.action,id=el.dataset.id,i=Number(el.dataset.index),questions=S.version?.definition.sections[S.section]?.questions;
 if(a==='reauth'){captureActive();await persistDraft();if(!confirmLeave())return;S.dirty=false;return login('Sign in to reconnect. Your saved collection drafts and queued responses stay on this device.');}if(a==='close')return closeDialog();if(a==='menu')return app.classList.toggle('menu-open');
 if(a==='logout'){const q=await cacheGet(userKey('queue'))||[];if(q.length&&!confirm(`${q.length} responses have not synced. Sign out and erase drafts and queued responses from this device?`))return;if(!confirmLeave())return;await request('logout',{});await clearStorage();closeDialog();S.boot=null;S.collect=null;S.answers={};S.version=null;S.client=null;S.results=null;S.response=null;S.dirty=false;history.replaceState(null,'',location.pathname);login();return;}
 if(a==='nav'){if(!confirmLeave())return;S.dirty=false;S.collect=null;S.answers={};S.results=null;S.response=null;const nav=el.dataset.nav;if(nav==='collection')return collection();if(S.offline)throw new Error('Connect to the internet to use the administration workspace.');await refresh();if(nav==='surveys')library();if(nav==='clients')clients();if(nav==='roles')roles();return;}
 if(a==='library'){if(!confirmLeave())return;S.dirty=false;await refresh();return library();}
 if(a==='library-prev'||a==='library-next'){S.page+=a==='library-next'?1:-1;return library();}
 if(a==='create'){const r=await api('create',{definition:newDefinition()});return openVersion(r.version.id);}
 if(a==='open-version'){if(!confirmLeave())return;return openVersion(id);}
 if(a==='save')return save();if(a==='word')return downloadWord(S.version.definition,S.version);
 if(a==='toggle-preview'){S.preview=!S.preview;return editor();}
 if(a==='section'){S.section=i;return editor();}
 if(a==='add-section')return mutateStructure(()=>{S.version.definition.sections.push({id:'s'+crypto.randomUUID().replaceAll('-',''),title:'New section',description:'',questions:[]});S.section=S.version.definition.sections.length-1;});
 if(a==='remove-section'){if(!confirm('Remove this section and its questions?'))return;return mutateStructure(()=>{S.version.definition.sections.splice(S.section,1);S.section=Math.max(0,S.section-1);});}
 if(a==='section-up'||a==='section-down')return mutateStructure(()=>{const list=S.version.definition.sections,n=S.section+(a==='section-up'?-1:1);[list[n],list[S.section]]=[list[S.section],list[n]];S.section=n;});
 if(a==='add-question')return mutateStructure(()=>questions.push({id:'q'+crypto.randomUUID().replaceAll('-',''),type:'short_text',label:'',help:'',required:false}));
 if(a==='q-remove')return mutateStructure(()=>questions.splice(i,1));
 if(a==='q-copy')return mutateStructure(()=>questions.splice(i+1,0,{...structuredClone(questions[i]),id:'q'+crypto.randomUUID().replaceAll('-','')}));
 if(a==='q-up'||a==='q-down')return mutateStructure(()=>{const n=i+(a==='q-up'?-1:1);[questions[n],questions[i]]=[questions[i],questions[n]];});
 if(a==='condition-add')return mutateStructure(()=>{questions[i].conditions??=[];questions[i].conditions.push({questionId:'',values:[]});});
 if(a==='condition-remove')return mutateStructure(()=>questions[i].conditions.splice(Number(el.dataset.conditionIndex),1));
 if(a==='request-review')return transition('request_review');if(a==='cancel-review')return transition('cancel_review');
 if(a==='review-return'||a==='review-approve')return dialog(a==='review-approve'?'Approve questionnaire':'Return with feedback',`<form id="review-form"><input type="hidden" name="decision" value="${a==='review-approve'?'approve':'return'}"><label>Review note<textarea name="note" required maxlength="5000" placeholder="Record what you checked or what needs changing…"></textarea></label><button type="submit" class="primary">${a==='review-approve'?'Approve survey':'Return to creator'}</button></form>`);
 if(a==='publish')return dialog('Publish this version?',`<p>Publishing fixes this version of the questionnaire. It will become available for client assignment. Future changes need a new draft and review.</p><p><b>${e(S.version.definition.title)} · Version ${S.version.version}</b></p>${btn('Publish version','confirm-publish','primary')}`);
 if(a==='confirm-publish'){closeDialog();return transition('publish');}
 if(a==='fork'||a==='copy-assigned'){if(S.dirty&&!confirmLeave())return;const r=await api('fork',{versionId:id||S.version.id});S.dirty=false;await refresh();return openVersion(r.version.id);}
 if(a==='clients')return clients();if(a==='open-client')return openClient(id);
 if(a==='client-tab'){S.clientTab=el.dataset.tab;if(S.clientTab==='results')return loadResults();if(S.clientTab==='audit')S.audit=(await api('audit',{clientId:S.client.client.id})).events;return clientView();}
 if(a==='create-client')return dialog('Create client workspace',`<form id="client-form"><label>Client name<input name="name" required minlength="2" maxlength="150" placeholder="Organisation name"></label><label>Initial client admin<select name="adminId" required><option value="">Select an existing account</option>${S.boot.people.map(p=>`<option value="${p.id}">${e(p.name)}</option>`).join('')}</select></label><div class="notice">The selected admin will have access to this client’s survey results and can manage its team.</div><button type="submit" class="primary">Create client</button></form>`);
 if(a==='assign-dialog'){const pub=S.boot.versions.filter(v=>v.state==='published');return dialog('Assign a published survey',`<form id="assign-form"><label>Published questionnaire<select name="versionId" required><option value="">Choose a published version</option>${pub.map(v=>`<option value="${v.id}">${e(v.title)} · v${v.version}</option>`).join('')}</select></label><p class="muted">This gives ${e(S.client.client.name)} access to distribute and reuse the questionnaire. Responses remain private to their client leadership.</p><button class="primary" type="submit" ${!pub.length?'disabled':''}>Assign survey</button></form>`);}
 if(a==='campaign-dialog')return dialog('Distribute assigned survey',`<form id="campaign-form"><input type="hidden" name="assignmentId" value="${id}"><label>Campaign name<input name="name" required minlength="2" maxlength="150" placeholder="e.g. Jigawa pilot · November 2026"></label><p class="muted">Active client team members can collect through the campaign link. Reuse this survey by creating additional campaigns.</p><button type="submit" class="primary">Create campaign</button></form>`);
 if(a==='assignment-status'){await api('assignment_status',{clientId:S.client.client.id,assignmentId:id,active:el.dataset.active==='true'});return reloadClient();}
 if(a==='campaign-status'){await api('campaign_status',{clientId:S.client.client.id,campaignId:id,active:el.dataset.active==='true'});return reloadClient();}
 if(a==='copy-link'){const url=location.origin+'/survey-studio/index.html?campaign='+id;try{await navigator.clipboard.writeText(url);toast('Sign-in link copied');}catch{dialog('Campaign sign-in link',`<label>Share with this client’s team<input readonly value="${e(url)}"></label><p>Only active members of the assigned client can open this survey.</p>`);}return;}
 if(a==='member-dialog')return memberDialog(id);if(a==='role-dialog')return roleDialog(id);
 if(a==='results-prev'||a==='results-next'){S.offset+=a==='results-next'?25:-25;return loadResults();}if(a==='refresh-results')return loadResults();if(a==='response')return response(id);
 if(a==='fix-queued'){const queue=await cacheGet(userKey('queue'))||[],entry=queue.find(x=>x.responseId===id);if(!entry||entry.syncCode!=='invalid_answers')return;await openCampaign(entry.campaignId);if(S.collect.version.id!==entry.versionId)throw new Error('The questionnaire version changed. Ask your client admin for help.');S.collect.responseId=entry.responseId;S.collect.capturedAt=entry.capturedAt;S.answers=entry.answers;S.answerIndex=Math.max(0,visibleQuestions(S.collect.version.definition,S.answers).findIndex(q=>q.id===entry.questionId));await persistDraft();await cacheSet(userKey('queue'),queue.filter(x=>x.responseId!==id));collector();return;}if(a==='open-campaign')return openCampaign(id);if(a==='answer-next'||a==='answer-prev')return nextAnswer(a==='answer-next'?1:-1);
 if(a==='close-collection'){captureActive();await persistDraft();history.replaceState(null,'',location.pathname);await collection();return toast('Draft saved on this device');}
 if(a==='back-questions'){S.collectReview=false;return collector();}
 if(a==='edit-answer'){S.answerIndex=visibleQuestions(S.collect.version.definition,S.answers).findIndex(q=>q.id===id);S.collectReview=false;return collector();}
 if(a==='submit-response')return submitResponse();if(a==='sync'){if(S.offline&&navigator.onLine)return boot();await syncQueue();await collection();return toast('Sync checked. Pending responses are shown above.');}
}
document.addEventListener('click',async ev=>{const el=ev.target.closest('[data-action]');if(!el)return;ev.preventDefault();if(el.disabled)return;el.disabled=true;try{await action(el);}catch(err){toast(err.message);}finally{if(el.isConnected)el.disabled=false;}});
let searchTimer;
document.addEventListener('input',ev=>{const el=ev.target;
 if(el.id==='library-search'){clearTimeout(searchTimer);S.search=el.value;S.page=0;searchTimer=setTimeout(()=>{const pos=el.selectionStart;library();const n=$('#library-search');n.focus();n.setSelectionRange(pos,pos);},250);return;}
 if(el.closest('#active-question')){captureActive();persistDraft().catch(()=>toast('Could not save on this device. Check available storage.'));return;}
 if(!canEdit())return;const qel=el.closest('[data-qindex]'),q=qel?S.version.definition.sections[S.section].questions[Number(qel.dataset.qindex)]:null;
 if(q&&el.dataset.conditionOption!==undefined){const c=q.conditions[Number(el.dataset.condition)];c.values=el.checked?[...new Set([...c.values,el.dataset.conditionOption])]:c.values.filter(v=>v!==el.dataset.conditionOption);markDirty();return;}if(q&&el.dataset.condition!==undefined){const c=q.conditions[Number(el.dataset.condition)];c[el.dataset.conditionField]=el.dataset.conditionField==='values'?el.value.split('\n').map(s=>s.trim()).filter(Boolean):el.value;markDirty();return;}
 if(q&&el.dataset.qfield){const k=el.dataset.qfield;if(['options','rows'].includes(k))q[k]=el.value.split('\n').map(s=>s.trim()).filter(Boolean);else if(['required','integer'].includes(k))q[k]=el.checked;else if(['min','max'].includes(k)){if(el.value==='')delete q[k];else q[k]=Number(el.value);}else q[k]=el.value;markDirty();return;}
 const k=el.dataset.field,d=S.version.definition,s=d.sections[S.section];if(k==='title'||k==='description')d[k]=el.value;if(k==='section-title')s.title=el.value;if(k==='section-description')s.description=el.value;if(k)markDirty();
});
document.addEventListener('change',async ev=>{const el=ev.target;try{
 if(el.id==='library-filter'){S.filter=el.value;S.page=0;library();}if(el.id==='library-sort'){S.sort=el.value;S.page=0;library();}
 if(el.id==='result-version'){S.resultVersion=el.value;S.offset=0;await loadResults();}if(el.id==='result-excluded'){S.includeExcluded=el.checked;S.offset=0;await loadResults();}
 if(el.closest('#role-form')&&el.name==='accountId'){const r=S.boot.roles.find(x=>x.account_id===el.value);for(const [name,key]of [['create','can_create'],['review','can_review'],['publish','can_publish'],['admin','is_admin']])$('#role-form').elements[name].checked=Boolean(r?.[key]);}
 if(el.dataset.conditionField==='questionId'&&canEdit()){const q=S.version.definition.sections[S.section].questions[Number(el.closest('[data-qindex]').dataset.qindex)];q.conditions[Number(el.dataset.condition)].questionId=el.value;q.conditions[Number(el.dataset.condition)].values=[];markDirty();editor();}if(el.dataset.qfield==='type'&&canEdit()){const q=S.version.definition.sections[S.section].questions[Number(el.closest('[data-qindex]').dataset.qindex)];q.type=el.value;if(q.type.includes('choice')||q.type==='dropdown')q.options??=['Option 1','Option 2'];if(q.type.includes('grid'))q.rows??=['Row 1','Row 2'];if(q.type==='rating'){q.min=1;q.max=5;}else if(q.type!=='number'){delete q.min;delete q.max;delete q.integer;}if(q.type==='statement')q.required=false;markDirty();editor();}
 }catch(err){toast(err.message);}});
document.addEventListener('submit',async ev=>{ev.preventDefault();const form=ev.target,fd=new FormData(form),values=Object.fromEntries(fd),button=$('button[type=submit]',form);if(button)button.disabled=true;try{
 if(form.id==='login-form'){await request('login',values);closeDialog();await boot();return;}
 if(form.id==='password-form'){await request('password',values);await boot();return;}
 if(form.id==='review-form'){closeDialog();await transition('review',values);return;}
 if(form.id==='client-form'){await api('create_client',values);closeDialog();await refresh();clients();toast('Client workspace created');return;}
 if(form.id==='assign-form'){await api('assign',{clientId:S.client.client.id,...values});closeDialog();await reloadClient();toast('Published survey assigned');return;}
 if(form.id==='campaign-form'){await api('campaign',{clientId:S.client.client.id,...values});closeDialog();S.clientTab='campaigns';await reloadClient();toast('Campaign created. Share its sign-in link with the client team.');return;}
 if(form.id==='member-form'){await api('member',{clientId:S.client.client.id,...values,active:fd.has('active')});closeDialog();await reloadClient();toast('Client access updated');return;}
 if(form.id==='role-form'){await api('set_role',{accountId:values.accountId,...Object.fromEntries(['create','review','publish','admin'].map(k=>[k,fd.has(k)]))});closeDialog();await refresh();if(S.boot.permissions.admin)roles();else library();toast('Studio permissions updated');return;}
 if(form.id==='flag-form'){await api('flag_response',{clientId:S.client.client.id,responseId:S.response.response.id,excluded:!S.response.excluded,note:values.note});closeDialog();S.response=null;await loadResults();toast('Result inclusion updated. Original response retained.');return;}
 }catch(err){if(form.id==='login-form'||form.id==='password-form')login(err.message,err.code==='password_change_required'||form.id==='password-form');else{let n=$('.form-error',form);if(!n){n=document.createElement('p');n.className='notice error form-error';n.setAttribute('role','alert');form.prepend(n);}n.textContent=err.message;}}finally{if(button?.isConnected)button.disabled=false;}});
window.addEventListener('beforeunload',ev=>{if(S.dirty){ev.preventDefault();ev.returnValue='';}});
window.addEventListener('online',async()=>{if(!S.boot)return;try{if(S.offline){await boot();return;}await syncQueue();if(S.nav==='collection'&&!S.collect)await collection();toast('Internet restored. Pending responses checked.');}catch(err){toast(err.message);}});
window.addEventListener('offline',()=>toast('You are offline. Downloaded collection surveys and drafts remain available.'));
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js',{scope:'./'}).catch(()=>{});
boot();
